    "question": "À propos des propriétés de la membrane plasmique :",
    "propositions": {
      "A": "La longueur des AG joue un rôle important dans la fluidité membranaire : plus les AG sont longs, plus la MP est fluide",
      "B": "Les PL peuvent effectuer trois types de mouvement différents : la diffusion latérale, la rotation et le flip-flop",
      "C": "L'importance du phénomène de diffusion latérale conduit à parler à propos de la mosaïque fluide de la MP",
      "D": "Les différents PL ne sont pas insérés de façon aléatoire dans les 2 hémi-couches de la MP",
      "E": "La répartition des PL entraîne une asymétrie dans la répartition des différents acides gras saturés ou insaturés, dans les deux hémi-couches de la MP"
    },
    "question_fr": "À propos des propriétés de la membrane plasmique :",
    "question_en": "Concerning plasma membrane properties:",
    "propositions_fr": {
      "A": "La longueur des AG joue un rôle important dans la fluidité membranaire : plus les AG sont longs, plus la MP est fluide",
      "B": "Les PL peuvent effectuer trois types de mouvement différents : la diffusion latérale, la rotation et le flip-flop",
      "C": "L'importance du phénomène de diffusion latérale conduit à parler à propos de la mosaïque fluide de la MP",
      "D": "Les différents PL ne sont pas insérés de façon aléatoire dans les 2 hémi-couches de la MP",
      "E": "La répartition des PL entraîne une asymétrie dans la répartition des différents acides gras saturés ou insaturés, dans les deux hémi-couches de la MP"
    },
    "propositions_en": {
      "A": "FA chain length plays a major role: the longer the FAs, the more fluid the PM",
      "B": "PLs can undergo three movement types: lateral diffusion, rotation, and flip-flop",
      "C": "The prominence of lateral diffusion supports the fluid mosaic model",
      "D": "Different PLs are not inserted randomly into the 2 leaflets of PM",
      "E": "PL distribution leads to asymmetric distribution of saturated/unsaturated FAs across the two leaflets"
    },
