    "question": "À propos du transport membranaire :",
    "propositions": {
      "A": "Le co-transporteur symport glucose/Na+ permet le transport d'une molécule de glucose contre un ion Na+ dans l'intestin",
      "B": "Le gradient électrochimique du Na+ du co-transporteur symport glucose/Na+ se fait dans le sens lumière de l'intestin -> entérocytes",
      "C": "Le transport actif primaire nécessite la présence des pompes ATPase qui peuvent être situées sur la face cytosolique de la membrane plasmique",
      "D": "Le glucose diffuse des entérocytes vers le vaisseau sanguin à travers une perméase uniporteur par une diffusion facilitée",
      "E": "Les cellules rénales possèdent le même type de GLUT que celles des cellules de l'intestin grêle"
    },
    "question_fr": "À propos du transport membranaire :",
    "question_en": "Concerning membrane transport:",
    "propositions_fr": {
      "A": "Le co-transporteur symport glucose/Na+ permet le transport d'une molécule de glucose contre un ion Na+ dans l'intestin",
      "B": "Le gradient électrochimique du Na+ du co-transporteur symport glucose/Na+ se fait dans le sens lumière de l'intestin -> entérocytes",
      "C": "Le transport actif primaire nécessite la présence des pompes ATPase qui peuvent être situées sur la face cytosolique de la membrane plasmique",
      "D": "Le glucose diffuse des entérocytes vers le vaisseau sanguin à travers une perméase uniporteur par une diffusion facilitée",
      "E": "Les cellules rénales possèdent le même type de GLUT que celles des cellules de l'intestin grêle"
    },
    "propositions_en": {
      "A": "Glucose/Na+ symporter transports one glucose molecule against one Na+ in intestine",
      "B": "Na+ electrochemical gradient drives transport from intestinal lumen into enterocytes",
      "C": "Primary active transport requires ATPase pumps located on cytosolic face of PM",
      "D": "Glucose diffuses from enterocytes to bloodstream via uniport permease by facilitated diffusion",
      "E": "Renal cells possess the identical GLUT transporter type as small intestine cells"
    },
