    "question": "À propos des microtubules (MT) :",
    "propositions": {
      "A": "Les molécules de tubuline libres s'intègrent dans le MT en formation en se fixant au niveau de la sous-unité bêta des molécules déjà présentes en son sein",
      "B": "La nucléation des MT se fait à travers une structure appelée gamma-TuRC",
      "C": "M-loop c'est une protéine qui assure l'attachement et la fixation de 13 protofilaments",
      "D": "Un centriole est constitué de 27 microtubules",
      "E": "La sévérine c'est une protéine qui permet de relier le cargo à transporter aux protéines motrices"
    },
    "question_fr": "À propos des microtubules (MT) :",
