    "question_fr": "La synthèse d'une chaîne polypeptidique au niveau du réticulum endoplasmique nécessite",
    "question_en": "The synthesis of a polypeptide chain at the endoplasmic reticulum requires:",
    "propositions_fr": {
      "A": "La synthèse préalable d'une séquence « signal » dans le cytoplasme.",
      "B": "La liaison d'une particule protéique reconnaissant la séquence signal (SRP).",
      "C": "La fermeture du translocon par la petite sous-unité ribosomale sur sa face cytosolique et par la protéine BiP sur sa face luminale.",
      "D": "L'excision de la séquence signal par une peptidase cytosolique.",
      "E": "Le détachement de la SRP de son récepteur."
    },
    "propositions_en": {
      "A": "Prior synthesis of a 'signal' sequence in the cytoplasm.",
      "B": "Binding of a protein particle recognizing the signal sequence (SRP).",
      "C": "Closure of the translocon by the small ribosomal subunit on its cytosolic side and by BiP on its luminal side.",
      "D": "Excision of the signal sequence by a cytosolic peptidase.",
      "E": "Detachment of SRP from its receptor."
    },
    "bonnes_reponses": [
      "A",
      "B"
    ],
    "faculty": "Mostaganem"
