      "D": "Les phospholipides synthétisés au REL peuvent être adressés aux membranes des mitochondries et des peroxysomes.",
      "E": "De nombreux médicaments et toxines sont capturés et hydrolysés par un cytochrome P450 selon un processus de détoxification au niveau du REL."
