    "question": "Concernant l'appareil de Golgi",
    "propositions": {
      "A": "L'AG est un organite pouvant prendre plusieurs formes différentes et est composé de dictyosomes.",
      "B": "L'AG est un organite polarisé ; sa face cis est tournée vers la membrane plasmique et prolongée par un réseau de canalicules.",
      "C": "L'ERGIC est l'ensemble des vésicules qui assurent la relation entre la face convexe et le RE.",
      "D": "Les vésicules assurant les échanges entre le RE et l'AG forment le réseau cis-Golgi.",
      "E": "Les vésicules bourgeonnant de la face trans de l'AG sont toutes destinées à la membrane plasmique."
    },
    "question_fr": "Concernant l'appareil de Golgi",
