    "question": "Concernant les peroxysomes",
    "propositions": {
      "A": "Les peroxysomes sont abondants dans les cellules hépatiques et rénales qui ont un rôle de détoxification.",
      "B": "Ils sont impliqués dans la respiration cellulaire.",
      "C": "Ils possèdent, comme le noyau, une double membrane.",
      "D": "Un peroxysome ne peut naître que s'il existe d'autres peroxysomes dans la cellule.",
      "E": "Ils sont le site d'oxydation des AG à chaîne courte."
    },
    "question_fr": "Concernant les peroxysomes",
