      "B": "They are involved in cellular respiration.",
      "C": "They possess, like the nucleus, a double membrane.",
      "D": "A peroxisome can only arise if other peroxisomes exist in the cell.",
      "E": "They are the site of short-chain fatty acid oxidation."
