      "B": "La quantité d'ADN passe de 1 à 0,5 unité, ce qui implique une division du matériel génétique en deux lots, un lot par nouvelle cellule.",
      "C": "L'ADN est copié à partir des brins existants par complémentarité de bases.",
      "D": "La molécule d'ADN est copiée à l'identique sauf pour les T qui deviennent des U.",
