    "question": "La réplication de l'ADN :",
    "propositions": {
      "A": "Se déroule selon un mode semi-conservatif : la moitié de l'ADN initial est conservée.",
      "B": "Se déroule selon un mode dispersif : des morceaux de l'ADN initial s'associent avec l'ADN nouvellement formé.",
      "C": "Se déroule selon un mode conservatif : une nouvelle molécule d'ADN est formée par photocopie de l'ancienne.",
      "D": "Permet la duplication de l'ADN en préservant le message initial et en permettant la réparation des erreurs éventuelles.",
      "E": "Aucune réponse."
    },
    "question_fr": "La réplication de l'ADN :",
    "question_en": "DNA replication:",
    "propositions_fr": {
      "A": "Se déroule selon un mode semi-conservatif : la moitié de l'ADN initial est conservée.",
      "B": "Se déroule selon un mode dispersif : des morceaux de l'ADN initial s'associent avec l'ADN nouvellement formé.",
      "C": "Se déroule selon un mode conservatif : une nouvelle molécule d'ADN est formée par photocopie de l'ancienne.",
      "D": "Permet la duplication de l'ADN en préservant le message initial et en permettant la réparation des erreurs éventuelles.",
      "E": "Aucune réponse."
    },
    "propositions_en": {
      "A": "Occurs in a semi-conservative manner: half of the initial DNA is conserved.",
      "B": "Occurs in a dispersive manner: fragments of original DNA associate with newly formed DNA.",
      "C": "Occurs in a conservative manner: a new DNA molecule is formed by photocopying the old one.",
      "D": "Allows DNA duplication while preserving the initial message and allowing repair of potential errors.",
      "E": "No answer."
    },
    "bonnes_reponses": [
      "A",
      "D"
    ],
